# PPT

# Generated by ChatGPT 4o
import cvxpy as cp
import numpy as np

def partial_transpose(rho, dims, sys=1):
    """
    Partial transpose of rho with respect to subsystem 'sys'
    dims: (dim_A, dim_B)
    """
    dA, dB = dims
    rho_pt = cp.Variable((dA*dB, dA*dB), complex=True)

    constraints = []
    for i in range(dA):
        for j in range(dA):
            for k in range(dB):
                for l in range(dB):
                    # Index mapping for partial transpose on subsystem B
                    i1 = i * dB + k
                    j1 = j * dB + l
                    i2 = i * dB + l
                    j2 = j * dB + k
                    constraints.append(rho_pt[i1, j1] == rho[i2, j2])
    return rho_pt, constraints

# Dimensions
dA, dB = 2, 2
d = dA * dB

# Define optimization variable (density matrix)
rho = cp.Variable((d, d), complex=True)

# Basic quantum constraints
constraints = [
    rho >> 0,
    cp.trace(rho) == 1,
]

# Add PPT constraints
rho_pt, pt_constraints = partial_transpose(rho, (dA, dB), sys=1)
constraints += pt_constraints
constraints.append(rho_pt >> 0)

# Objective (example: maximize overlap with target)
target = np.eye(d) / d
objective = cp.Maximize(cp.real(cp.trace(target @ rho)))

# Solve
prob = cp.Problem(objective, constraints)
prob.solve()
print("Optimal value:", prob.value)

# SEP

# Toeplitz

# Generated by ChatGPT 4o
def toeplitz_matrix(n):
    """
    Create a symmetric Toeplitz matrix variable.
    """
    # Only 2n-1 diagonals determine an n x n Toeplitz matrix
    diag_entries = [cp.Variable() for _ in range(2*n - 1)]
    T = cp.Variable((n, n), symmetric=True)

    constraints = []
    for i in range(n):
        for j in range(n):
            constraints.append(T[i, j] == diag_entries[i - j + n - 1])
    return T, constraints

# Example usage
n = 4
T, toeplitz_constraints = toeplitz_matrix(n)
constraints = [T >> 0] + toeplitz_constraints

# Dummy objective
objective = cp.Maximize(cp.trace(T))
prob = cp.Problem(objective, constraints)
prob.solve()
print("Toeplitz matrix:\n", T.value)

# Generated by ChatGPT 4o
toeplitz_matrices = []
constraints = []
for _ in range(3):  # k Toeplitz matrices
    T, c = toeplitz_matrix(n)
    toeplitz_matrices.append(T)
    constraints += c
